/**
 * 1.13c `D2Common_11050` (`0x6FDA54E0`, `Monsters.cpp:1245`):
 * Resolves the `Missiles.txt` key configured on `MonStats.txt` for `(classId, mode)`:
 * - `4` (`MONMODE_ATTACK1` / `A1`) -> `MissA1`
 * - `5` (`MONMODE_ATTACK2` / `A2`) -> `MissA2`
 * - `7` (`MONMODE_CAST` / `C`) -> `MissC`
 * - `8` (`MONMODE_SKILL1` / `S1`) -> `MissS1`
 * - `9` (`MONMODE_SKILL2` / `S2`) -> `MissS2`
 * - `10` (`MONMODE_SKILL3` / `S3`) -> `MissS3`
 * - `11` (`MONMODE_SKILL4` / `S4`) -> `MissS4`
 * - `14` (`MONMODE_SEQUENCE` / `SQ`) -> `MissSQ`
 */
function resolveModeMissileFromEntry(
  entry: MonsterModeMissiles113c,
  mode: number | string,
): string | undefined {
  if (typeof mode === 'number') {
    switch (mode) {
      case 4:
        return entry.A1
      case 5:
        return entry.A2
      case 7:
        return entry.C
      case 8:
        return entry.S1
      case 9:
        return entry.S2
      case 10:
        return entry.S3
      case 11:
        return entry.S4
      case 14:
        return entry.SQ
      default:
        return undefined
    }
  }
  const normalized = mode.trim().toUpperCase()
  switch (normalized) {
    case 'A1':
    case 'MISSA1':
    case '4':
      return entry.A1
    case 'A2':
    case 'MISSA2':
    case '5':
      return entry.A2
    case 'C':
    case 'SC':
    case 'MISSC':
    case '7':
      return entry.C
    case 'S1':
    case 'MISSS1':
    case '8':
      return entry.S1
    case 'S2':
    case 'MISSS2':
    case '9':
      return entry.S2
    case 'S3':
    case 'MISSS3':
    case '10':
      return entry.S3
    case 'S4':
    case 'MISSS4':
    case '11':
      return entry.S4
    case 'SQ':
    case 'MISSSQ':
    case '14':
      return entry.SQ
    default:
      return undefined
  }
}

